        ("invite.who", "Text: Schools, community organisations, and the organisers of fest", "Schools, community organisations, and the organisers of festivals and public events."),
        ("invite.what.term", "Text: What we bring", "What we bring"),
        ("invite.what", "Text: A table of student projects, run by the students who built t", "A table of student projects, run by the students who built them, with mentors on hand."),
        ("invite.how.term", "Text: How to ask", "How to ask"),
        ("invite.how", "Text: Get in touch with the date, the place and who will be there.", "Get in touch with the date, the place and who will be there. We will tell you what we can bring."),
