        ("fund.records.term", "Text: If you are funded", "If you are funded"),
        ("fund.records", "Text: Your school may sign a short agreement. Keep every receipt a", "Your school may sign a short agreement. Keep every receipt and a ledger of what you spend; you may be asked for a midpoint update, and a final report is due within two weeks of finishing."),
