        ("faq.title", "Text: Questions", "Questions"),
        ("faq.1.q", "Text: Do I need an expensive project?", "Do I need an expensive project?"),
        ("faq.1.a", "Text: No. Cost is not a measure of quality. A focused project with", "No. Cost is not a measure of quality. A focused project with good evidence can be excellent using simple materials."),
        ("faq.2.q", "Text: Can I use an idea I saw online?", "Can I use an idea I saw online?"),
        ("faq.2.a", "Text: You can learn from existing ideas, but copying a project is ", "You can learn from existing ideas, but copying a project is not acceptable. Acknowledge the source and develop your own question, comparison, improvement or application."),
        ("faq.3.q", "Text: What if my experiment does not work?", "What if my experiment does not work?"),
        ("faq.3.a", "Text: Record what happened, work out the likely causes, improve th", "Record what happened, work out the likely causes, improve the method where it is safe to, and explain what you learned. Judges value honesty about failed attempts."),
        ("faq.4.q", "Text: Can a university or company mentor help me?", "Can a university or company mentor help me?"),
        ("faq.4.a", "Text: Yes, as long as the help is appropriate and disclosed, and y", "Yes, as long as the help is appropriate and disclosed, and you can explain all the work yourself."),
        ("faq.5.q", "Text: Can I use AI?", "Can I use AI?"),
        ("faq.5.a", "Text: Responsible help may be allowed, but it must not replace you", "Responsible help may be allowed, but it must not replace your work or understanding. Declare any significant use and check what it produces."),
        ("faq.6.q", "Text: Can my parent build the prototype?", "Can my parent build the prototype?"),
        ("faq.6.a", "Text: A parent can help safely with a task you are not allowed to ", "A parent can help safely with a task you are not allowed to do, but you must design the project, make the key decisions and say what help you had."),
        ("faq.7.q", "Text: Can I change my project after approval?", "Can I change my project after approval?"),
        ("faq.7.a", "Text: Small changes are normal. Changes to the question, budget, s", "Small changes are normal. Changes to the question, budget, safety, ethics or anything involving people should be agreed with your teacher and may need Foundation approval."),
        ("faq.8.q", "Text: What if my proposal is not selected?", "What if my proposal is not selected?"),
        ("faq.8.a", "Text: Where the competition allows, you will get feedback to impro", "Where the competition allows, you will get feedback to improve it. A rejected proposal does not mean you are not capable of STEM."),
        ("cta.title", "Text: Help a project reach the fair", "Help a project reach the fair"),
