class Command(BaseCommand):
    help = "Create or update the editable copy on the hand-built pages."

    def add_arguments(self, parser):
        parser.add_argument("--page", help="Only this page.")
        parser.add_argument(
            "--overwrite",
            action="store_true",
            help="Also reset text that has been edited since it was seeded.",
        )

    def handle(self, *args, **options):
        only = options.get("page")
        overwrite = options["overwrite"]
        created_n = updated_n = kept_n = 0

        for page, entries in BLOCKS.items():
            if only and page != only:
                continue
            for key, label, value in entries:
                block, created = PageBlock.objects.get_or_create(
                    page=page, key=key,
                    defaults={"label": label, "value": value, "is_published": True},
                )
                if created:
                    created_n += 1
                    continue
                # Re-running must not silently undo someone's editing. The label
                # is ours to keep current; the text is theirs.
                block.label = label
                if overwrite:
                    block.value = value
                    updated_n += 1
                else:
                    kept_n += 1
                block.save(update_fields=["label", "value", "updated_at"])

        self.stdout.write(
            self.style.SUCCESS(
                f"{created_n} created, {updated_n} reset, {kept_n} left as edited; "
                f"{PageBlock.objects.count()} blocks total"
            )
        )
